std::istream_iterator<int> eos; // End-of-stream (Sentinel)

std::istream_iterator<int> input_it(std::cin);
// Initializer: reads the first value T from the stream

while (input_it != eos) {
    int current_val = *input_it; // Dereference yields the current value

    // Pre-increment reads the next value from the stream
    ++input_it;
}
// std::istream_iterator is an Input Iterator (single-pass)
// Usage: std::vector<int> v(input_it, eos);
